/// Full scan of all authoritative RCP databases.
/// Ensures the D-Bus tree exactly matches the state derived from plugin schemas.
pub async fn refresh_full_tree(&self) -> Result<()> {
    let mut active_paths = HashSet::new();

    // Everything on the system is derived from a plugin schema.
    // We project two primary branches: OVSDB (network) and NonNet (everything else).

    // 1. Project Network State (OVSDB)
    if let Err(e) = self.publish_schema_derived_ovsdb(&mut active_paths).await {
        tracing::warn!("OVSDB schema projection failed: {}", e);
    }

    // 2. Project Plugin State (NonNet)
    if let Err(e) = self.publish_schema_derived_nonnet(&mut active_paths).await {
        tracing::warn!("NonNet schema projection failed: {}", e);
    }

    // 3. Remove stale objects that no longer exist in any authoritative store
    self.remove_stale_publications(&active_paths).await?;

    Ok(())
}

/// Project OVSDB state using the "net" plugin schema logic.
async fn publish_schema_derived_ovsdb(&self, active_paths: &mut HashSet<String>) -> Result<()> {
    let dump = self.ovsdb.dump_open_vswitch().await?;

    if let Value::Object(tables) = dump {
        for (table_name, rows_val) in tables.iter() {
            if let Some(rows) = rows_val.as_array() {
                for row in rows {
                    let mut row_obj = row.clone();
                    let id = self.extract_uuid(&row_obj);

                    // Tag as derived from the 'net' plugin schema
                    if let Some(obj) = row_obj.as_object_mut() {
                        obj.insert("plugin_id".into(), Value::from("net"));
                        obj.insert("derived_from_schema".into(), Value::from(true));
                        obj.insert("object_type".into(), Value::from(table_name.as_str()));
                    }

                    let path = format!(
                        "/org/opdbus/v1/plugins/net/{}/{}",
                        sanitize_path_segment(table_name),
                        sanitize_path_segment(&id)
                    );

                    self.publish_object(&path, row_obj).await?;
                    active_paths.insert(path);
                }
            }
        }
    }

    Ok(())
}

/// Project NonNet state using plugin-defined schemas.
async fn publish_schema_derived_nonnet(&self, active_paths: &mut HashSet<String>) -> Result<()> {
    let request = op_jsonrpc::protocol::JsonRpcRequest::new("list_dbs", Value::Array(vec![]));
    let response = self.nonnet.handle_request(request).await;

    let dbs = response
        .result
        .and_then(|v: Value| v.as_array().map(|a| a.to_vec()))
        .unwrap_or_default();

    for db_name_val in dbs {
        if let Some(db_name) = db_name_val.as_str() {
            let schema_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                "get_schema",
                Value::Array(vec![Value::from(db_name)]),
            );
            let schema_resp = self.nonnet.handle_request(schema_req).await;

            if let Some(tables) = schema_resp
                .result
                .and_then(|schema| schema.get("tables").and_then(|v| v.as_object().cloned()))
            {
                for (table_name, _) in tables.iter() {
                    let select_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                        "transact",
                        Value::Array(vec![
                            Value::from(db_name),
                            simd_json::json!({"op": "select", "table": table_name}),
                        ]),
                    );
                    let resp = self.nonnet.handle_request(select_req).await;

                    if let Some(rows) = resp
                        .result
                        .and_then(|r: Value| r.as_array().and_then(|a| a.first().cloned()))
                        .and_then(|r: Value| r.get("rows").cloned())
                        .and_then(|v: Value| v.as_array().map(|a| a.to_vec()))
                    {
                        for row in rows {
                            // Objects from NonNet are already tagged with derived_from_schema 
                            // during the load_from_plugins phase in NonNetDb.
                            if row.get("derived_from_schema").and_then(|v| v.as_bool()) != Some(true) {
                                continue;
                            }

                            let id = self.extract_uuid(&row);
                            let plugin_id = row.get("plugin_id").and_then(|v| v.as_str()).unwrap_or(table_name);
                            let object_type = row.get("object_type").and_then(|v| v.as_str()).unwrap_or(table_name);

                            let path = format!(
                                "/org/opdbus/v1/plugins/{}/{}/{}",
                                sanitize_path_segment(plugin_id),
                                sanitize_path_segment(object_type),
                                sanitize_path_segment(&id)
                            );

                            self.publish_object(&path, row.clone()).await?;
                            active_paths.insert(path);
                        }
                    }
                }
            }
        }
    }

    Ok(())
}

pub async fn load_from_plugins(&self, plugins: &HashMap<String, Value>) {
    let mut state = self.state.write().await;

    // Build schema and tables from plugin state
    let mut schema_tables = simd_json::value::owned::Object::new();
    let mut tables = HashMap::new();

    for (db_name, value) in plugins {
        // Skip network plugin
        if db_name == "net" {
            continue;
        }

        // Infer columns from the value structure
        let columns = infer_columns(value);
        schema_tables.insert(db_name.clone(), json!({"columns": columns}));

        // Convert value to rows
        let rows = value_to_rows_with_plugin(value, db_name);
        tables.insert(db_name.clone(), rows.clone());

        // Broadcast initial load as update
        let _ = self.update_tx.send(NonNetUpdate {
            db_name: NONNET_DB_NAME.to_string(),
            table: db_name.clone(),
            rows,
        });
    }

