/// Convert a value to table rows, preserving keys as IDs where appropriate
fn value_to_rows_with_plugin(value: &Value, plugin_id: &str) -> Vec<Value> {
    match value {
        Value::Array(arr) => arr.clone(),
        Value::Object(map) => {
            let mut rows = Vec::new();
            for (k, v) in map.iter() {
                match v {
                    Value::Object(row_obj) => {
                        let mut row = row_obj.clone();
                        // If the key is a map of objects (e.g., "services": { "ssh": { ... } })
                        // we should probably recurse or flatten. For now, if the inner values 
                        // are objects, treat the key 'k' as the object type or part of the ID.

                        // Check if this is a map of objects (typical for plugin state)
                        let is_collection = row.iter().all(|(_, val)| val.is_object());

                        if is_collection {
                            for (inner_k, inner_v) in row.iter() {
                                if let Value::Object(inner_obj) = inner_v {
                                    let mut inner_row = inner_obj.clone();
                                    // Inject canonical schema metadata
                                    inner_row.insert("id".into(), Value::from(inner_k.as_str()));
                                    inner_row.insert("name".into(), Value::from(inner_k.as_str()));
                                    inner_row.insert("object_type".into(), Value::from(k.as_str()));
                                    inner_row.insert("plugin_id".into(), Value::from(plugin_id));
                                    inner_row.insert("derived_from_schema".into(), Value::from(true));
                                    rows.push(Value::Object(inner_row));
                                }
                            }
                        } else {
                            // Single object - inject key as ID if not present
                            if row.get("id").is_none() && row.get("name").is_none() {
                                row.insert("id".into(), Value::from(k.as_str()));
                            }
                            row.insert("object_type".into(), Value::from(k.as_str()));
                            row.insert("plugin_id".into(), Value::from(plugin_id));
                            row.insert("derived_from_schema".into(), Value::from(true));
                            rows.push(Value::Object(row));
                        }
                    }
                    Value::Array(arr) => {
                        for item in arr.iter() {
                            if let Value::Object(item_obj) = item {
                                let mut row = item_obj.clone();
                                row.insert("object_type".into(), Value::from(k.as_str()));
                                row.insert("plugin_id".into(), Value::from(plugin_id));
                                row.insert("derived_from_schema".into(), Value::from(true));
                                rows.push(Value::Object(row));
                            } else {
                                rows.push(item.clone());
                            }
                        }
                    }
                    _ => {
                        // Scalar value - wrap in a row
                        rows.push(json!({
                            "id": k.as_str(),
                            "value": v.clone(),
                            "object_type": "property",
                            "plugin_id": plugin_id,
                            "derived_from_schema": true
                        }));
                    }
                }
            }
            if rows.is_empty() {
                vec![value.clone()]
            } else {
                rows
            }
        }
        _ => vec![value.clone()],
    }
}

