/// Validate a desired plugin state.
///
/// Runtime Definition Policy:
/// 1. The live plugin code is the primary authority for its own schema.
/// 2. The schema catalog is used as a fallback or for offline reference.
pub fn validate_plugin_state(&self, plugin_name: &str, desired: &Value) -> Result<()> {
    let plugin = self.get_plugin(plugin_name);

    // 1. Try to validate using the live plugin's internal schema first
    if let Some(ref p) = plugin {
        if let Some(schema) = p.schema() {
            let validation = schema.validate(desired);
            if validation.valid {
                return Ok(());
            }
            return Err(anyhow!(
                "State rejected by live plugin schema '{}': {}",
                plugin_name,
                validation.errors.join("; ")
            ));
        }
    }

    // 2. Fallback to the schema catalog (reference store)
    let validation = self
        .schema_catalog
        .read()
        .validate(plugin_name, desired)
        .ok_or_else(|| anyhow!("Schema '{}' not found in live plugin or catalog", plugin_name))?;

    if validation.valid {
        return Ok(());
    }

    Err(anyhow!(
        "State rejected by catalog schema '{}': {}",
        plugin_name,
        validation.errors.join("; ")
    ))
}

