/// Full scan of all authoritative RCP databases.
/// Ensures the D-Bus tree exactly matches database state.
pub async fn refresh_full_tree(&self) -> Result<()> {
    let mut active_paths = HashSet::new();

    // 1. Project Network State (OVSDB)
    if let Err(e) = self.publish_ovsdb_snapshot(&mut active_paths).await {
        tracing::warn!("OVSDB projection failed: {}", e);
    }

    // 2. Project Plugin State (NonNet)
    if let Err(e) = self.publish_nonnet_snapshot(&mut active_paths).await {
        tracing::warn!("NonNet projection failed: {}", e);
    }

    // 3. Remove stale objects that no longer exist in any authoritative store
    self.remove_stale_publications(&active_paths).await?;

    Ok(())
}

/// Project OVSDB state
async fn publish_ovsdb_snapshot(&self, active_paths: &mut HashSet<String>) -> Result<()> {
    let dump = self.ovsdb.dump_open_vswitch().await?;

    if let Value::Object(tables) = dump {
        for (table_name, rows_val) in tables.iter() {
            if let Some(rows) = rows_val.as_array() {
                for row in rows {
                    let id = self.extract_uuid(row);

                    let path = format!(
                        "/org/opdbus/v1/ovsdb/{}/{}",
                        sanitize_path_segment(table_name),
                        sanitize_path_segment(&id)
                    );

                    self.publish_object(&path, row.clone()).await?;
                    active_paths.insert(path);

                    // Alias to Freedesktop paths for compatibility
                    if table_name == "Interface" || table_name == "Port" {
                        let compat_path = format!(
                            "/org/freedesktop/network1/link/{}",
                            sanitize_path_segment(&id)
                        );
                        self.publish_object(&compat_path, row.clone()).await?;
                        active_paths.insert(compat_path);
                    }
                }
            }
        }
    }

    Ok(())
}

/// Project NonNet state
async fn publish_nonnet_snapshot(&self, active_paths: &mut HashSet<String>) -> Result<()> {
    let request = op_jsonrpc::protocol::JsonRpcRequest::new("list_dbs", Value::Array(vec![]));
    let response = self.nonnet.handle_request(request).await;

    let dbs = response
        .result
        .and_then(|v: Value| v.as_array().map(|a| a.to_vec()))
        .unwrap_or_default();

    for db_name_val in dbs {
        if let Some(db_name) = db_name_val.as_str() {
            let schema_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                "get_schema",
                Value::Array(vec![Value::from(db_name)]),
            );
            let schema_resp = self.nonnet.handle_request(schema_req).await;

            if let Some(tables) = schema_resp
                .result
                .and_then(|schema| schema.get("tables").and_then(|v| v.as_object().cloned()))
            {
                for (table_name, _) in tables.iter() {
                    let select_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                        "transact",
                        Value::Array(vec![
                            Value::from(db_name),
                            simd_json::json!({"op": "select", "table": table_name}),
                        ]),
                    );
                    let resp = self.nonnet.handle_request(select_req).await;

                    if let Some(rows) = resp
                        .result
                        .and_then(|r: Value| r.as_array().and_then(|a| a.first().cloned()))
                        .and_then(|r: Value| r.get("rows").cloned())
                        .and_then(|v: Value| v.as_array().map(|a| a.to_vec()))
                    {
                        for row in rows {
                            let id = self.extract_uuid(&row);
                            let path = format!(
                                "/org/opdbus/v1/plugins/{}/{}",
                                sanitize_path_segment(table_name),
                                sanitize_path_segment(&id)
                            );

                            self.publish_object(&path, row.clone()).await?;
                            active_paths.insert(path);
                        }
                    }
                }
            }
        }
    }

    Ok(())
}

