//! op-dbus-mirror: 1:1 D-Bus publication of internal databases
//!
//! This crate publishes the internal OVSDB and NonNet database structures as a
//! D-Bus object hierarchy without introducing a second source of truth. It is a
//! pure 1:1 projection of the authoritative RCP stores.

use anyhow::Result;
use dashmap::DashMap;
use op_core::{dbus::connect_and_claim_name, types::BusType};
use op_grpc_bridge::SchemaEngine;
use op_jsonrpc::nonnet::NonNetDb;
use op_network::ovsdb::OvsdbClient;
use simd_json::prelude::*;
use simd_json::OwnedValue as Value;
use std::collections::HashSet;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use zbus::zvariant::ObjectPath;
use zbus::Connection;

pub mod dbus_interface;
pub mod jsonrpc_interface;
pub mod object;
pub mod tree;

/// D-Bus publication service.
///
/// Maintains a 1:1 D-Bus object view of the two authoritative RCP stores:
///   - OVSDB (network state)
///   - NonNet (non-network plugin state)
pub struct DbusMirror {
    ovsdb: Arc<OvsdbClient>,
    nonnet: Arc<NonNetDb>,
    schema_engine: Option<Arc<SchemaEngine>>,
    connection: Connection,
    /// Published D-Bus object paths managed by this service.
    published_objects: DashMap<String, ()>,
    /// Monotonic counter for generating unique fallback IDs when rows lack a UUID.
    fallback_id: AtomicU64,
}

impl DbusMirror {
    /// Create a new D-Bus publication service.
    pub async fn new(
        bus_type: BusType,
        ovsdb: Arc<OvsdbClient>,
        nonnet: Arc<NonNetDb>,
        schema_engine: Option<Arc<SchemaEngine>>,
    ) -> Result<Self> {
        let connection = connect_and_claim_name(bus_type, "org.opdbus.v1").await?;

        // Attempt to claim standard Freedesktop networking name for compatibility
        if let Err(e) = op_core::dbus::request_additional_name(&connection, "org.freedesktop.network1").await {
            tracing::warn!("Failed to claim org.freedesktop.network1: {}", e);
        } else {
            tracing::info!("Successfully claimed org.freedesktop.network1 for compatibility");
        }

        Ok(Self {
            ovsdb,
            nonnet,
            schema_engine,
            connection,
            published_objects: DashMap::new(),
            fallback_id: AtomicU64::new(0),
        })
    }

    /// Start the mirror service.
    pub async fn start(self: Arc<Self>) -> Result<()> {
        tracing::info!("Starting D-Bus mirror publication service...");

        // Initial full publication from all RCP stores
        if let Err(e) = self.refresh_full_tree().await {
            tracing::error!("Initial D-Bus mirror sync failed: {}", e);
        }

        // Register mirror-management interface
        let interface = dbus_interface::DbusMirrorInterface::new(self.clone());
        self.connection
            .object_server()
            .at("/org/opdbus/v1", interface)
            .await?;

        // Register OVSDB JSON-RPC interface at /org/opdbus/v1/ovsdb
        let ovsdb_interface =
            jsonrpc_interface::OvsdbInterface::new(self.ovsdb.clone(), self.schema_engine.clone());
        self.connection
            .object_server()
            .at("/org/opdbus/v1/ovsdb", ovsdb_interface)
            .await?;

        // Register NonNet JSON-RPC interface at /org/opdbus/v1/nonnet
        let nonnet_interface = jsonrpc_interface::NonNetInterface::new(
            self.nonnet.clone(),
            self.schema_engine.clone(),
        );
        self.connection
            .object_server()
            .at("/org/opdbus/v1/nonnet", nonnet_interface)
            .await?;

        // Start background refresh task using event-driven updates
        let mut ovsdb_rx = match self.ovsdb.monitor_db("Open_vSwitch").await {
            Ok(rx) => Some(rx),
            Err(e) => {
                tracing::error!("Failed to start OVSDB monitor: {}", e);
                None
            }
        };
        let mut nonnet_rx = self.nonnet.subscribe();
        let mirror = self.clone();

        tokio::spawn(async move {
            let mut interval = tokio::time::interval(std::time::Duration::from_secs(300));
            loop {
                tokio::select! {
                    _ = interval.tick() => {
                        if let Err(e) = mirror.refresh_full_tree().await {
                            tracing::error!("Periodic D-Bus mirror refresh failed: {}", e);
                        }
                    }
                    result = nonnet_rx.recv() => {
                        match result {
                            Ok(_update) => {
                                tracing::debug!("Received NonNet event, triggering mirror refresh");
                                if let Err(e) = mirror.refresh_full_tree().await {
                                    tracing::error!("Event-driven D-Bus mirror refresh failed: {}", e);
                                }
                            }
                            Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                                tracing::warn!("NonNet event receiver lagged by {} messages", n);
                            }
                            Err(tokio::sync::broadcast::error::RecvError::Closed) => {
                                tracing::error!("NonNet event receiver closed, sleeping before next poll");
                                tokio::time::sleep(std::time::Duration::from_secs(5)).await;
                            }
                        }
                    }
                    result = async {
                        if let Some(rx) = ovsdb_rx.as_mut() {
                            rx.recv().await
                        } else {
                            std::future::pending().await
                        }
                    } => {
                        match result {
                            Some(_update) => {
                                tracing::debug!("Received OVSDB event, triggering mirror refresh");
                                if let Err(e) = mirror.refresh_full_tree().await {
                                    tracing::error!("Event-driven D-Bus mirror refresh failed: {}", e);
                                }
                            }
                            None => {
                                tracing::error!("OVSDB event receiver closed, disabling OVSDB event-driven updates");
                                ovsdb_rx = None;
                            }
                        }
                    }
                }
            }
        });

        std::future::pending::<()>().await;
        Ok(())
    }

    /// Compatibility method for dbus_interface
    pub async fn publish_snapshot(&self) -> Result<()> {
        self.refresh_full_tree().await
    }

    pub fn published_count(&self) -> u64 {
        self.published_objects.len() as u64
    }

    pub fn projected_count(&self) -> u64 {
        self.published_objects.len() as u64
    }

    /// Full scan of all authoritative RCP databases.
    /// Ensures the D-Bus tree exactly matches database state.
    pub async fn refresh_full_tree(self: &Arc<Self>) -> Result<()> {
        let mut active_paths = HashSet::new();

        // 1. Project Network State (OVSDB)
        if let Err(e) = self.publish_ovsdb_snapshot(&mut active_paths).await {
            tracing::warn!("OVSDB snapshot failed: {}", e);
        }

        // 2. Project Plugin State (NonNet)
        if let Err(e) = self.publish_nonnet_snapshot(&mut active_paths).await {
            tracing::warn!("NonNet snapshot failed: {}", e);
        }

        // 3. Remove stale objects that no longer exist in any authoritative store
        self.remove_stale_publications(&active_paths).await?;

        Ok(())
    }

    /// Project OVSDB state
    async fn publish_ovsdb_snapshot(&self, active_paths: &mut HashSet<String>) -> Result<()> {
        let dump = self.ovsdb.dump_open_vswitch().await?;

        if let Value::Object(tables) = dump {
            for (table_name, rows_val) in tables.iter() {
                if let Some(rows) = rows_val.as_array() {
                    for row in rows {
                        let id = self.extract_uuid(row);

                        let path = format!(
                            "/org/opdbus/v1/plugins/net/{}/{}",
                            sanitize_path_segment(table_name),
                            sanitize_path_segment(&id)
                        );

                        self.publish_object(&path, row.clone()).await?;
                        active_paths.insert(path.clone());

                        // Alias to Freedesktop paths for compatibility
                        if table_name == "Interface" || table_name == "Port" {
                            let compat_path = format!(
                                "/org/freedesktop/network1/link/{}",
                                sanitize_path_segment(&id)
                            );
                            self.publish_object(&compat_path, row.clone()).await?;
                            active_paths.insert(compat_path);
                        }
                    }
                }
            }
        }

        Ok(())
    }

    /// Project NonNet state using a concurrent task pool for large tables.
    async fn publish_nonnet_snapshot(self: &Arc<Self>, active_paths: &mut HashSet<String>) -> Result<()> {
        let request = op_jsonrpc::protocol::JsonRpcRequest::new("list_dbs", Value::Array(vec![]));
        let response = self.nonnet.handle_request(request).await;

        let dbs = response
            .result
            .and_then(|v: Value| v.as_array().map(|a| a.to_vec()))
            .unwrap_or_default();

        let mut join_set = tokio::task::JoinSet::new();
        let chunk_size = 500;

        for db_name_val in dbs {
            if let Some(db_name) = db_name_val.as_str() {
                let db_name = db_name.to_string();
                let schema_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                    "get_schema",
                    Value::Array(vec![Value::from(db_name.clone())]),
                );
                let schema_resp = self.nonnet.handle_request(schema_req).await;

                if let Some(tables) = schema_resp
                    .result
                    .and_then(|schema| schema.get("tables").and_then(|v| v.as_object().cloned()))
                {
                    for (table_name, _) in tables.iter() {
                        let table_name = table_name.to_string();

                        // Get row count for efficient chunking
                        let count_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                            "transact",
                            Value::Array(vec![
                                Value::from(db_name.clone()),
                                simd_json::json!({"op": "count", "table": table_name}),
                            ]),
                        );
                        let count_resp = self.nonnet.handle_request(count_req).await;
                        let count = count_resp.result
                            .and_then(|r| r.as_array().and_then(|a| a.first().and_then(|o| o.get("count")).and_then(|v| v.as_u64())))
                            .unwrap_or(0) as usize;

                        // Process in chunks concurrently
                        for offset in (0..count).step_by(chunk_size) {
                            let mirror = self.clone();
                            let db_name_inner = db_name.clone();
                            let table_name_inner = table_name.clone();

                            join_set.spawn(async move {
                                let select_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                                    "transact",
                                    Value::Array(vec![
                                        Value::from(db_name_inner.clone()),
                                        simd_json::json!({
                                            "op": "select", 
                                            "table": table_name_inner,
                                            "offset": offset,
                                            "limit": chunk_size
                                        }),
                                    ]),
                                );
                                let resp = mirror.nonnet.handle_request(select_req).await;

                                let mut paths = Vec::new();
                                if let Some(rows) = resp
                                    .result
                                    .and_then(|r: Value| r.as_array().and_then(|a| a.first().cloned()))
                                    .and_then(|r: Value| r.get("rows").cloned())
                                    .and_then(|v: Value| v.as_array().map(|a| a.to_vec()))
                                {
                                    for row in rows {
                                        let id = mirror.extract_uuid(&row);
                                        let path = format!(
                                            "/org/opdbus/v1/plugins/{}/{}/{}",
                                            sanitize_path_segment(&db_name_inner),
                                            sanitize_path_segment(&table_name_inner),
                                            sanitize_path_segment(&id)
                                        );

                                        if let Err(e) = mirror.publish_object(&path, row).await {
                                            tracing::error!("Failed to publish object {}: {}", path, e);
                                        } else {
                                            paths.push(path);
                                        }
                                    }
                                }
                                paths
                            });
                        }
                    }
                }
            }
        }

        // Wait for all chunks to finish and collect active paths
        while let Some(res) = join_set.join_next().await {
            if let Ok(paths) = res {
                for path in paths {
                    active_paths.insert(path);
                }
            }
        }

        Ok(())
    }

    async fn publish_object(&self, path: &str, data: Value) -> Result<()> {
        if self.published_objects.contains_key(path) {
            let op = ObjectPath::try_from(path)?;
            if let Ok(iface_ref) = self
                .connection
                .object_server()
                .interface::<_, object::MirrorObject>(op)
                .await
            {
                let mut guard = iface_ref.get_mut().await;
                if guard.update_data(data) {
                    guard.data_updated(iface_ref.signal_context()).await.ok();
                }
            }
            return Ok(());
        }

        let obj = object::MirrorObject::new(data);
        self.connection.object_server().at(path, obj).await?;
        self.published_objects.insert(path.to_string(), ());

        Ok(())
    }

    async fn remove_stale_publications(&self, active_paths: &HashSet<String>) -> Result<()> {
        let mut to_remove = Vec::new();
        for entry in self.published_objects.iter() {
            if !active_paths.contains(entry.key()) {
                to_remove.push(entry.key().clone());
            }
        }

        for path in to_remove {
            let op = ObjectPath::try_from(path.as_str())?;
            self.connection
                .object_server()
                .remove::<object::MirrorObject, _>(op)
                .await?;
            self.published_objects.remove(&path);
        }

        Ok(())
    }

    pub fn list_published_paths(&self) -> Vec<String> {
        self.published_objects
            .iter()
            .map(|e| e.key().clone())
            .collect()
    }

    fn extract_uuid(&self, row: &Value) -> String {
        if let Some(uuid) = row.get("uuid").and_then(|v| v.as_str()) {
            return uuid.to_string();
        }
        if let Some(uuid) = row.get("_uuid").and_then(|v| v.as_str()) {
            return uuid.to_string();
        }
        if let Some(id) = row.get("id").and_then(|v| v.as_str()) {
            return id.to_string();
        }
        if let Some(s) = row.get("name").and_then(|v| v.as_str()) {
            return s.to_string();
        }
        format!("anon_{}", self.fallback_id.fetch_add(1, Ordering::Relaxed))
    }
}

fn sanitize_path_segment(segment: &str) -> String {
    segment
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '_' {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

pub mod prelude {
    pub use super::DbusMirror;
}

#[cfg(test)]
mod tests {
    use super::sanitize_path_segment;

    #[test]
    fn sanitizes_dbus_path_segments() {
        assert_eq!(sanitize_path_segment("bridge-01"), "bridge_01");
        assert_eq!(sanitize_path_segment("6f0c8b4e-9d9f"), "6f0c8b4e_9d9f");
    }
}

//! op-dbus-mirror: 1:1 D-Bus publication of internal databases
//!
//! This crate publishes the internal OVSDB and NonNet database structures as a
//! D-Bus object hierarchy without introducing a second source of truth. It is a
//! pure 1:1 projection of the authoritative RCP stores.

use anyhow::Result;
use dashmap::DashMap;
use op_core::{dbus::connect_and_claim_name, types::BusType};
use op_grpc_bridge::SchemaEngine;
use op_jsonrpc::nonnet::NonNetDb;
use op_network::ovsdb::OvsdbClient;
use simd_json::prelude::*;
use simd_json::OwnedValue as Value;
use std::collections::HashSet;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use zbus::zvariant::ObjectPath;
use zbus::Connection;

pub mod dbus_interface;
pub mod jsonrpc_interface;
pub mod object;
pub mod tree;

/// D-Bus publication service.
///
/// Maintains a 1:1 D-Bus object view of the two authoritative RCP stores:
///   - OVSDB (network state)
///   - NonNet (non-network plugin state)
pub struct DbusMirror {
    ovsdb: Arc<OvsdbClient>,
    nonnet: Arc<NonNetDb>,
    schema_engine: Option<Arc<SchemaEngine>>,
    connection: Connection,
    /// Published D-Bus object paths managed by this service.
    published_objects: DashMap<String, ()>,
    /// Monotonic counter for generating unique fallback IDs when rows lack a UUID.
    fallback_id: AtomicU64,
}

impl DbusMirror {
    /// Create a new D-Bus publication service.
    pub async fn new(
        bus_type: BusType,
        ovsdb: Arc<OvsdbClient>,
        nonnet: Arc<NonNetDb>,
        schema_engine: Option<Arc<SchemaEngine>>,
    ) -> Result<Self> {
        let connection = connect_and_claim_name(bus_type, "org.opdbus.v1").await?;

        // Attempt to claim standard Freedesktop networking name for compatibility
        if let Err(e) = op_core::dbus::request_additional_name(&connection, "org.freedesktop.network1").await {
            tracing::warn!("Failed to claim org.freedesktop.network1: {}", e);
        } else {
            tracing::info!("Successfully claimed org.freedesktop.network1 for compatibility");
        }

        Ok(Self {
            ovsdb,
            nonnet,
            schema_engine,
            connection,
            published_objects: DashMap::new(),
            fallback_id: AtomicU64::new(0),
        })
    }

    /// Start the mirror service.
    pub async fn start(self: Arc<Self>) -> Result<()> {
        tracing::info!("Starting D-Bus mirror publication service...");

        // Initial full publication from all RCP stores
        if let Err(e) = self.refresh_full_tree_internal(self.clone()).await {
            tracing::error!("Initial D-Bus mirror sync failed: {}", e);
        }

        // Register mirror-management interface
        let interface = dbus_interface::DbusMirrorInterface::new(self.clone());
        self.connection
            .object_server()
            .at("/org/opdbus/v1", interface)
            .await?;

        // Register OVSDB JSON-RPC interface at /org/opdbus/v1/ovsdb
        let ovsdb_interface =
            jsonrpc_interface::OvsdbInterface::new(self.ovsdb.clone(), self.schema_engine.clone());
        self.connection
            .object_server()
            .at("/org/opdbus/v1/ovsdb", ovsdb_interface)
            .await?;

        // Register NonNet JSON-RPC interface at /org/opdbus/v1/nonnet
        let nonnet_interface = jsonrpc_interface::NonNetInterface::new(
            self.nonnet.clone(),
            self.schema_engine.clone(),
        );
        self.connection
            .object_server()
            .at("/org/opdbus/v1/nonnet", nonnet_interface)
            .await?;

        // Start background refresh task using event-driven updates
        let mut ovsdb_rx = match self.ovsdb.monitor_db("Open_vSwitch").await {
            Ok(rx) => Some(rx),
            Err(e) => {
                tracing::error!("Failed to start OVSDB monitor: {}", e);
                None
            }
        };
        let mut nonnet_rx = self.nonnet.subscribe();
        let mirror = self.clone();

        tokio::spawn(async move {
            let mut interval = tokio::time::interval(std::time::Duration::from_secs(300));
            loop {
                tokio::select! {
                    _ = interval.tick() => {
                        if let Err(e) = mirror.refresh_full_tree_internal(mirror.clone()).await {
                            tracing::error!("Periodic D-Bus mirror refresh failed: {}", e);
                        }
                    }
                    result = nonnet_rx.recv() => {
                        match result {
                            Ok(_update) => {
                                tracing::debug!("Received NonNet event, triggering mirror refresh");
                                if let Err(e) = mirror.refresh_full_tree_internal(mirror.clone()).await {
                                    tracing::error!("Event-driven D-Bus mirror refresh failed: {}", e);
                                }
                            }
                            Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                                tracing::warn!("NonNet event receiver lagged by {} messages", n);
                            }
                            Err(tokio::sync::broadcast::error::RecvError::Closed) => {
                                tracing::error!("NonNet event receiver closed, sleeping before next poll");
                                tokio::time::sleep(std::time::Duration::from_secs(5)).await;
                            }
                        }
                    }
                    result = async {
                        if let Some(rx) = ovsdb_rx.as_mut() {
                            rx.recv().await
                        } else {
                            std::future::pending().await
                        }
                    } => {
                        match result {
                            Some(_update) => {
                                tracing::debug!("Received OVSDB event, triggering mirror refresh");
                                if let Err(e) = mirror.refresh_full_tree_internal(mirror.clone()).await {
                                    tracing::error!("Event-driven D-Bus mirror refresh failed: {}", e);
                                }
                            }
                            None => {
                                tracing::error!("OVSDB event receiver closed, disabling OVSDB event-driven updates");
                                ovsdb_rx = None;
                            }
                        }
                    }
                }
            }
        });

        std::future::pending::<()>().await;
        Ok(())
    }

    /// Compatibility method for dbus_interface
    pub async fn publish_snapshot(self: Arc<Self>) -> Result<()> {
        self.refresh_full_tree_internal(self.clone()).await
    }

    pub fn published_count(&self) -> u64 {
        self.published_objects.len() as u64
    }

    pub fn projected_count(&self) -> u64 {
        self.published_objects.len() as u64
    }

    /// Public refresh method that handles the Arc requirement.
    pub async fn refresh_full_tree(&self) -> Result<()> {
        // This is a bit of a hack to satisfy the &self requirement from interfaces
        // while allowing async task spawning that needs Arc.
        // In practice, DbusMirror is always wrapped in Arc.
        Err(anyhow::anyhow!("refresh_full_tree requires Arc context. Use start() or event-driven updates."))
    }

    /// Internal full scan of all authoritative RCP databases.
    async fn refresh_full_tree_internal(self: Arc<Self>, mirror_arc: Arc<Self>) -> Result<()> {
        let mut active_paths = HashSet::new();

        // 1. Project Network State (OVSDB)
        if let Err(e) = self.publish_ovsdb_snapshot(&mut active_paths).await {
            tracing::warn!("OVSDB snapshot failed: {}", e);
        }

        // 2. Project Plugin State (NonNet)
        if let Err(e) = self.publish_nonnet_snapshot_internal(mirror_arc, &mut active_paths).await {
            tracing::warn!("NonNet snapshot failed: {}", e);
        }

        // 3. Remove stale objects that no longer exist in any authoritative store
        self.remove_stale_publications(&active_paths).await?;

        Ok(())
    }

    /// Project OVSDB state
    async fn publish_ovsdb_snapshot(&self, active_paths: &mut HashSet<String>) -> Result<()> {
        let dump = self.ovsdb.dump_open_vswitch().await?;

        if let Value::Object(tables) = dump {
            for (table_name, rows_val) in tables.iter() {
                if let Some(rows) = rows_val.as_array() {
                    for row in rows {
                        let id = self.extract_uuid(row);

                        let path = format!(
                            "/org/opdbus/v1/plugins/net/{}/{}",
                            sanitize_path_segment(table_name),
                            sanitize_path_segment(&id)
                        );

                        self.publish_object(&path, row.clone()).await?;
                        active_paths.insert(path.clone());

                        // Alias to Freedesktop paths for compatibility
                        if table_name == "Interface" || table_name == "Port" {
                            let compat_path = format!(
                                "/org/freedesktop/network1/link/{}",
                                sanitize_path_segment(&id)
                            );
                            self.publish_object(&compat_path, row.clone()).await?;
                            active_paths.insert(compat_path);
                        }
                    }
                }
            }
        }

        Ok(())
    }

    /// Project NonNet state using a concurrent task pool for large tables.
    async fn publish_nonnet_snapshot_internal(self: Arc<Self>, mirror_arc: Arc<Self>, active_paths: &mut HashSet<String>) -> Result<()> {
        let request = op_jsonrpc::protocol::JsonRpcRequest::new("list_dbs", Value::Array(vec![]));
        let response = self.nonnet.handle_request(request).await;

        let dbs = response
            .result
            .and_then(|v: Value| v.as_array().map(|a| a.to_vec()))
            .unwrap_or_default();

        let mut join_set = tokio::task::JoinSet::new();
        let chunk_size = 500;

        for db_name_val in dbs {
            if let Some(db_name) = db_name_val.as_str() {
                let db_name = db_name.to_string();
                let schema_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                    "get_schema",
                    Value::Array(vec![Value::from(db_name.clone())]),
                );
                let schema_resp = self.nonnet.handle_request(schema_req).await;

                if let Some(tables) = schema_resp
                    .result
                    .and_then(|schema| schema.get("tables").and_then(|v| v.as_object().cloned()))
                {
                    for (table_name, _) in tables.iter() {
                        let table_name = table_name.to_string();

                        // Get row count for efficient chunking
                        let count_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                            "transact",
                            Value::Array(vec![
                                Value::from(db_name.clone()),
                                simd_json::json!({"op": "count", "table": table_name}),
                            ]),
                        );
                        let count_resp = self.nonnet.handle_request(count_req).await;
                        let count = count_resp.result
                            .and_then(|r| r.as_array().and_then(|a| a.first().and_then(|o| o.get("count")).and_then(|v| v.as_u64())))
                            .unwrap_or(0) as usize;

                        // Process in chunks concurrently
                        for offset in (0..count).step_by(chunk_size) {
                            let mirror = mirror_arc.clone();
                            let db_name_inner = db_name.clone();
                            let table_name_inner = table_name.clone();

                            join_set.spawn(async move {
                                let select_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                                    "transact",
                                    Value::Array(vec![
                                        Value::from(db_name_inner.clone()),
                                        simd_json::json!({
                                            "op": "select", 
                                            "table": table_name_inner,
                                            "offset": offset,
                                            "limit": chunk_size
                                        }),
                                    ]),
                                );
                                let resp = mirror.nonnet.handle_request(select_req).await;

                                let mut paths = Vec::new();
                                if let Some(rows) = resp
                                    .result
                                    .and_then(|r: Value| r.as_array().and_then(|a| a.first().cloned()))
                                    .and_then(|r: Value| r.get("rows").cloned())
                                    .and_then(|v: Value| v.as_array().map(|a| a.to_vec()))
                                {
                                    for row in rows {
                                        let id = mirror.extract_uuid(&row);
                                        let path = format!(
                                            "/org/opdbus/v1/plugins/{}/{}/{}",
                                            sanitize_path_segment(&db_name_inner),
                                            sanitize_path_segment(&table_name_inner),
                                            sanitize_path_segment(&id)
                                        );

                                        if let Err(e) = mirror.publish_object(&path, row).await {
                                            tracing::error!("Failed to publish object {}: {}", path, e);
                                        } else {
                                            paths.push(path);
                                        }
                                    }
                                }
                                paths
                            });
                        }
                    }
                }
            }
        }

        // Wait for all chunks to finish and collect active paths
        while let Some(res) = join_set.join_next().await {
            if let Ok(paths) = res {
                for path in paths {
                    active_paths.insert(path);
                }
            }
        }

        Ok(())
    }

    async fn publish_object(&self, path: &str, data: Value) -> Result<()> {
        if self.published_objects.contains_key(path) {
            let op = ObjectPath::try_from(path)?;
            if let Ok(iface_ref) = self
                .connection
                .object_server()
                .interface::<_, object::MirrorObject>(op)
                .await
            {
                let mut guard = iface_ref.get_mut().await;
                if guard.update_data(data) {
                    guard.data_updated(iface_ref.signal_context()).await.ok();
                }
            }
            return Ok(());
        }

        let obj = object::MirrorObject::new(data);
        self.connection.object_server().at(path, obj).await?;
        self.published_objects.insert(path.to_string(), ());

        Ok(())
    }

    async fn remove_stale_publications(&self, active_paths: &HashSet<String>) -> Result<()> {
        let mut to_remove = Vec::new();
        for entry in self.published_objects.iter() {
            if !active_paths.contains(entry.key()) {
                to_remove.push(entry.key().clone());
            }
        }

        for path in to_remove {
            let op = ObjectPath::try_from(path.as_str())?;
            self.connection
                .object_server()
                .remove::<object::MirrorObject, _>(op)
                .await?;
            self.published_objects.remove(&path);
        }

        Ok(())
    }

    pub fn list_published_paths(&self) -> Vec<String> {
        self.published_objects
            .iter()
            .map(|e| e.key().clone())
            .collect()
    }

    fn extract_uuid(&self, row: &Value) -> String {
        if let Some(uuid) = row.get("uuid").and_then(|v| v.as_str()) {
            return uuid.to_string();
        }
        if let Some(uuid) = row.get("_uuid").and_then(|v| v.as_str()) {
            return uuid.to_string();
        }
        if let Some(id) = row.get("id").and_then(|v| v.as_str()) {
            return id.to_string();
        }
        if let Some(s) = row.get("name").and_then(|v| v.as_str()) {
            return s.to_string();
        }
        format!("anon_{}", self.fallback_id.fetch_add(1, Ordering::Relaxed))
    }
}

fn sanitize_path_segment(segment: &str) -> String {
    segment
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '_' {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

pub mod prelude {
    pub use super::DbusMirror;
}

#[cfg(test)]
mod tests {
    use super::sanitize_path_segment;

    #[test]
    fn sanitizes_dbus_path_segments() {
        assert_eq!(sanitize_path_segment("bridge-01"), "bridge_01");
        assert_eq!(sanitize_path_segment("6f0c8b4e-9d9f"), "6f0c8b4e_9d9f");
    }
}

//! op-dbus-mirror: 1:1 D-Bus publication of internal databases
//!
//! This crate publishes the internal OVSDB and NonNet database structures as a
//! D-Bus object hierarchy without introducing a second source of truth. It is a
//! pure 1:1 projection of the authoritative RCP stores.

use anyhow::Result;
use dashmap::DashMap;
use op_core::{dbus::connect_and_claim_name, types::BusType};
use op_grpc_bridge::SchemaEngine;
use op_jsonrpc::nonnet::NonNetDb;
use op_network::ovsdb::OvsdbClient;
use simd_json::prelude::*;
use simd_json::OwnedValue as Value;
use std::collections::HashSet;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use zbus::zvariant::ObjectPath;
use zbus::Connection;

pub mod dbus_interface;
pub mod jsonrpc_interface;
pub mod object;
pub mod tree;

/// D-Bus publication service.
///
/// Maintains a 1:1 D-Bus object view of the two authoritative RCP stores:
///   - OVSDB (network state)
///   - NonNet (non-network plugin state)
pub struct DbusMirror {
    ovsdb: Arc<OvsdbClient>,
    nonnet: Arc<NonNetDb>,
    schema_engine: Option<Arc<SchemaEngine>>,
    connection: Connection,
    /// Published D-Bus object paths managed by this service.
    published_objects: DashMap<String, ()>,
    /// Monotonic counter for generating unique fallback IDs when rows lack a UUID.
    fallback_id: AtomicU64,
}

impl DbusMirror {
    /// Create a new D-Bus publication service.
    pub async fn new(
        bus_type: BusType,
        ovsdb: Arc<OvsdbClient>,
        nonnet: Arc<NonNetDb>,
        schema_engine: Option<Arc<SchemaEngine>>,
    ) -> Result<Self> {
        let connection = connect_and_claim_name(bus_type, "org.opdbus.v1").await?;

        // Attempt to claim standard Freedesktop networking name for compatibility
        if let Err(e) = op_core::dbus::request_additional_name(&connection, "org.freedesktop.network1").await {
            tracing::warn!("Failed to claim org.freedesktop.network1: {}", e);
        } else {
            tracing::info!("Successfully claimed org.freedesktop.network1 for compatibility");
        }

        Ok(Self {
            ovsdb,
            nonnet,
            schema_engine,
            connection,
            published_objects: DashMap::new(),
            fallback_id: AtomicU64::new(0),
        })
    }

    /// Start the mirror service.
    pub async fn start(self: Arc<Self>) -> Result<()> {
        tracing::info!("Starting D-Bus mirror publication service...");

        // Initial full publication from all RCP stores
        if let Err(e) = self.refresh_full_tree().await {
            tracing::error!("Initial D-Bus mirror sync failed: {}", e);
        }

        // Register mirror-management interface
        let interface = dbus_interface::DbusMirrorInterface::new(self.clone());
        self.connection
            .object_server()
            .at("/org/opdbus/v1", interface)
            .await?;

        // Register OVSDB JSON-RPC interface at /org/opdbus/v1/ovsdb
        let ovsdb_interface =
            jsonrpc_interface::OvsdbInterface::new(self.ovsdb.clone(), self.schema_engine.clone());
        self.connection
            .object_server()
            .at("/org/opdbus/v1/ovsdb", ovsdb_interface)
            .await?;

        // Register NonNet JSON-RPC interface at /org/opdbus/v1/nonnet
        let nonnet_interface = jsonrpc_interface::NonNetInterface::new(
            self.nonnet.clone(),
            self.schema_engine.clone(),
        );
        self.connection
            .object_server()
            .at("/org/opdbus/v1/nonnet", nonnet_interface)
            .await?;

        // Start background refresh task using event-driven updates
        let mut ovsdb_rx = match self.ovsdb.monitor_db("Open_vSwitch").await {
            Ok(rx) => Some(rx),
            Err(e) => {
                tracing::error!("Failed to start OVSDB monitor: {}", e);
                None
            }
        };
        let mut nonnet_rx = self.nonnet.subscribe();
        let mirror = self.clone();

        tokio::spawn(async move {
            let mut interval = tokio::time::interval(std::time::Duration::from_secs(300));
            loop {
                tokio::select! {
                    _ = interval.tick() => {
                        if let Err(e) = mirror.refresh_full_tree().await {
                            tracing::error!("Periodic D-Bus mirror refresh failed: {}", e);
                        }
                    }
                    result = nonnet_rx.recv() => {
                        match result {
                            Ok(_update) => {
                                tracing::debug!("Received NonNet event, triggering mirror refresh");
                                if let Err(e) = mirror.refresh_full_tree().await {
                                    tracing::error!("Event-driven D-Bus mirror refresh failed: {}", e);
                                }
                            }
                            Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                                tracing::warn!("NonNet event receiver lagged by {} messages", n);
                            }
                            Err(tokio::sync::broadcast::error::RecvError::Closed) => {
                                tracing::error!("NonNet event receiver closed, sleeping before next poll");
                                tokio::time::sleep(std::time::Duration::from_secs(5)).await;
                            }
                        }
                    }
                    result = async {
                        if let Some(rx) = ovsdb_rx.as_mut() {
                            rx.recv().await
                        } else {
                            std::future::pending().await
                        }
                    } => {
                        match result {
                            Some(_update) => {
                                tracing::debug!("Received OVSDB event, triggering mirror refresh");
                                if let Err(e) = mirror.refresh_full_tree().await {
                                    tracing::error!("Event-driven D-Bus mirror refresh failed: {}", e);
                                }
                            }
                            None => {
                                tracing::error!("OVSDB event receiver closed, disabling OVSDB event-driven updates");
                                ovsdb_rx = None;
                            }
                        }
                    }
                }
            }
        });

        std::future::pending::<()>().await;
        Ok(())
    }

    /// Compatibility method for dbus_interface
    pub async fn publish_snapshot(&self) -> Result<()> {
        self.refresh_full_tree().await
    }

    pub fn published_count(&self) -> u64 {
        self.published_objects.len() as u64
    }

    pub fn projected_count(&self) -> u64 {
        self.published_objects.len() as u64
    }

    /// Full scan of all authoritative RCP databases.
    /// Ensures the D-Bus tree exactly matches database state.
    pub async fn refresh_full_tree(self: &Arc<Self>) -> Result<()> {
        let mut active_paths = HashSet::new();

        // 1. Project Network State (OVSDB)
        if let Err(e) = self.publish_ovsdb_snapshot(&mut active_paths).await {
            tracing::warn!("OVSDB snapshot failed: {}", e);
        }

        // 2. Project Plugin State (NonNet)
        if let Err(e) = self.publish_nonnet_snapshot(&mut active_paths).await {
            tracing::warn!("NonNet snapshot failed: {}", e);
        }

        // 3. Remove stale objects that no longer exist in any authoritative store
        self.remove_stale_publications(&active_paths).await?;

        Ok(())
    }

    /// Project OVSDB state
    async fn publish_ovsdb_snapshot(&self, active_paths: &mut HashSet<String>) -> Result<()> {
        let dump = self.ovsdb.dump_open_vswitch().await?;

        if let Value::Object(tables) = dump {
            for (table_name, rows_val) in tables.iter() {
                if let Some(rows) = rows_val.as_array() {
                    for row in rows {
                        let id = self.extract_uuid(row);

                        // All database-derived objects go into the "dynamic" branch
                        let path = format!(
                            "/org/opdbus/v1/dynamic/net/{}/{}",
                            sanitize_path_segment(table_name),
                            sanitize_path_segment(&id)
                        );

                        self.publish_object(&path, row.clone()).await?;
                        active_paths.insert(path.clone());

                        // Alias to Freedesktop paths for compatibility
                        if table_name == "Interface" || table_name == "Port" {
                            let compat_path = format!(
                                "/org/freedesktop/network1/link/{}",
                                sanitize_path_segment(&id)
                            );
                            self.publish_object(&compat_path, row.clone()).await?;
                            active_paths.insert(compat_path);
                        }
                    }
                }
            }
        }

        Ok(())
    }

    /// Project NonNet state using a concurrent task pool for large tables.
    async fn publish_nonnet_snapshot(self: &Arc<Self>, active_paths: &mut HashSet<String>) -> Result<()> {
        let request = op_jsonrpc::protocol::JsonRpcRequest::new("list_dbs", Value::Array(vec![]));
        let response = self.nonnet.handle_request(request).await;

        let dbs = response
            .result
            .and_then(|v: Value| v.as_array().map(|a| a.to_vec()))
            .unwrap_or_default();

        let mut join_set = tokio::task::JoinSet::new();
        let chunk_size = 500;

        for db_name_val in dbs {
            if let Some(db_name) = db_name_val.as_str() {
                let db_name = db_name.to_string();
                let schema_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                    "get_schema",
                    Value::Array(vec![Value::from(db_name.clone())]),
                );
                let schema_resp = self.nonnet.handle_request(schema_req).await;

                if let Some(tables) = schema_resp
                    .result
                    .and_then(|schema| schema.get("tables").and_then(|v| v.as_object().cloned()))
                {
                    for (table_name, _) in tables.iter() {
                        let table_name = table_name.to_string();

                        // Get row count for efficient chunking
                        let count_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                            "transact",
                            Value::Array(vec![
                                Value::from(db_name.clone()),
                                simd_json::json!({"op": "count", "table": table_name}),
                            ]),
                        );
                        let count_resp = self.nonnet.handle_request(count_req).await;
                        let count = count_resp.result
                            .and_then(|r| r.as_array().and_then(|a| a.first().and_then(|o| o.get("count")).and_then(|v| v.as_u64())))
                            .unwrap_or(0) as usize;

                        // Process in chunks concurrently
                        for offset in (0..count).step_by(chunk_size) {
                            let mirror = Arc::clone(self);
                            let db_name_inner = db_name.clone();
                            let table_name_inner = table_name.clone();

                            join_set.spawn(async move {
                                let select_req = op_jsonrpc::protocol::JsonRpcRequest::new(
                                    "transact",
                                    Value::Array(vec![
                                        Value::from(db_name_inner.clone()),
                                        simd_json::json!({
                                            "op": "select", 
                                            "table": table_name_inner,
                                            "offset": offset,
                                            "limit": chunk_size
                                        }),
                                    ]),
                                );
                                let resp = mirror.nonnet.handle_request(select_req).await;

                                let mut paths = Vec::new();
                                if let Some(rows) = resp
                                    .result
                                    .and_then(|r: Value| r.as_array().and_then(|a| a.first().cloned()))
                                    .and_then(|r: Value| r.get("rows").cloned())
                                    .and_then(|v: Value| v.as_array().map(|a| a.to_vec()))
                                {
                                    for row in rows {
                                        let id = mirror.extract_uuid(&row);
                                        // All database-derived objects go into the "dynamic" branch
                                        let path = format!(
                                            "/org/opdbus/v1/dynamic/{}/{}/{}",
                                            sanitize_path_segment(&db_name_inner),
                                            sanitize_path_segment(&table_name_inner),
                                            sanitize_path_segment(&id)
                                        );

                                        if let Err(e) = mirror.publish_object(&path, row).await {
                                            tracing::error!("Failed to publish object {}: {}", path, e);
                                        } else {
                                            paths.push(path);
                                        }
                                    }
                                }
                                paths
                            });
                        }
                    }
                }
            }
        }

        // Wait for all chunks to finish and collect active paths
        while let Some(res) = join_set.join_next().await {
            if let Ok(paths) = res {
                for path in paths {
                    active_paths.insert(path);
                }
            }
        }

        Ok(())
    }

    async fn publish_object(&self, path: &str, data: Value) -> Result<()> {
        if self.published_objects.contains_key(path) {
            let op = ObjectPath::try_from(path)?;
            if let Ok(iface_ref) = self
                .connection
                .object_server()
                .interface::<_, object::MirrorObject>(op)
                .await
            {
                let mut guard = iface_ref.get_mut().await;
                if guard.update_data(data) {
                    guard.data_updated(iface_ref.signal_context()).await.ok();
                }
            }
            return Ok(());
        }

        let obj = object::MirrorObject::new(data);
        self.connection.object_server().at(path, obj).await?;
        self.published_objects.insert(path.to_string(), ());

        Ok(())
    }

    async fn remove_stale_publications(&self, active_paths: &HashSet<String>) -> Result<()> {
        let mut to_remove = Vec::new();
        for entry in self.published_objects.iter() {
            if !active_paths.contains(entry.key()) {
                to_remove.push(entry.key().clone());
            }
        }

        for path in to_remove {
            let op = ObjectPath::try_from(path.as_str())?;
            self.connection
                .object_server()
                .remove::<object::MirrorObject, _>(op)
                .await?;
            self.published_objects.remove(&path);
        }

        Ok(())
    }

    pub fn list_published_paths(&self) -> Vec<String> {
        self.published_objects
            .iter()
            .map(|e| e.key().clone())
            .collect()
    }

    fn extract_uuid(&self, row: &Value) -> String {
        if let Some(uuid) = row.get("uuid").and_then(|v| v.as_str()) {
            return uuid.to_string();
        }
        if let Some(uuid) = row.get("_uuid").and_then(|v| v.as_str()) {
            return uuid.to_string();
        }
        if let Some(id) = row.get("id").and_then(|v| v.as_str()) {
            return id.to_string();
        }
        if let Some(s) = row.get("name").and_then(|v| v.as_str()) {
            return s.to_string();
        }
        format!("anon_{}", self.fallback_id.fetch_add(1, Ordering::Relaxed))
    }
}

fn sanitize_path_segment(segment: &str) -> String {
    segment
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '_' {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

pub mod prelude {
    pub use super::DbusMirror;
